<script setup lang="ts">
import {computed, onMounted, onUnmounted, ref} from 'vue'; import {api, type Status, type Video, type Trajectory, type Model} from './api';
const video=ref<Video|null>(null), trajectory=ref<Trajectory|null>(null), status=ref<Status>({state:'idle',runId:null,videoId:null,stage:'Готово'}), saved=ref<any[]>([]), error=ref(''), playing=ref(false), time=ref(0), speed=ref(1), view=ref<'map'|'space'>('map'), modelId=ref(''); const settings=ref({sampleHz:5,maxImageSize:640,maxFeatures:1500,threads:2,overlap:5}); let timer:number|undefined;
const model=computed<Model|undefined>(()=>trajectory.value?.models.find(m=>m.id===modelId.value)||trajectory.value?.models[0]); const samples=computed(()=>model.value?.samples||[]); const progress=computed(()=>status.value.total?Math.round((status.value.processed||0)/status.value.total*100):0); const current=computed(()=>samples.value.reduce((a,s)=>Math.abs(s.timeSec-time.value)<Math.abs(a.timeSec-time.value)?s:a,samples.value[0]));
async function refresh(){try{status.value=await api.status(); if(status.value.state==='running') timer=window.setTimeout(refresh,900)}catch(e){error.value=(e as Error).message}}
async function upload(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;error.value='';try{video.value=await api.upload(f)}catch(e){error.value=(e as Error).message}}
async function start(){if(!video.value)return;error.value='';try{status.value=await api.start(video.value.id,settings.value);refresh()}catch(e){error.value=(e as Error).message}}
async function load(id:string){try{trajectory.value=await api.result(id);modelId.value=trajectory.value.primaryModelId; video.value=trajectory.value.video}catch(e){error.value=(e as Error).message}}
async function loadSaved(){try{saved.value=await api.results()}catch{saved.value=[]}}
function toggle(){playing.value=!playing.value;if(playing.value){const tick=()=>{if(!playing.value)return;time.value=Math.min(video.value?.durationSec||0,time.value+.05*speed.value);if(time.value>=(video.value?.durationSec||0))playing.value=false;else requestAnimationFrame(tick)};requestAnimationFrame(tick)}}
function exportData(format:'json'|'csv'){if(!trajectory.value)return;window.open(`/api/results/${trajectory.value.runId}/export?format=${format}`,'_blank')}
onMounted(()=>{refresh();loadSaved()});onUnmounted(()=>clearTimeout(timer));
</script>
<template><div class="app-shell"><header><div class="brand"><span class="mark">∿</span><span>SLAM / trajectory lab</span></div><span class="header-note">Локальная рабочая область</span></header><main><section class="intro"><div><p class="eyebrow">КАМЕРА · MP4</p><h1>Восстановите путь<br>из видеозаписи</h1><p class="lede">Загрузите ролик, запустите реконструкцию и сопоставьте движение камеры с каждым кадром.</p></div><div class="upload-box"><label class="upload-label"><input type="file" accept="video/mp4,video/*" @change="upload"><span class="upload-icon">＋</span><strong>{{video?'Заменить видео':'Выбрать MP4'}}</strong><small>{{video?.name||'До запуска файл остаётся на вашем компьютере'}}</small></label><button class="primary" :disabled="!video||status.state==='running'" @click="start">{{status.state==='running'?'Обработка…':'Запустить восстановление'}}</button></div></section>
<div v-if="error" class="error">{{error}} <button @click="error=''">Закрыть</button></div><section v-if="status.state==='running'" class="run-status panel"><div><span class="eyebrow">В ПРОЦЕССЕ</span><h2>{{status.stage||'Обрабатываем видео'}}</h2><p>{{status.processed||0}} из {{status.total||'—'}} кадров · интерфейс доступен</p></div><div class="progress"><span :style="{width:progress+'%'}"></span><b>{{progress}}%</b></div><button class="secondary" @click="status.runId&&api.cancel(status.runId).then(s=>status=s)">Отменить</button></section>
<section v-if="trajectory" class="workspace"><div class="workspace-top"><div><p class="eyebrow">РЕЗУЛЬТАТ {{trajectory.runId.slice(0,8)}}</p><h2>{{trajectory.video.name}}</h2></div><div class="actions"><button class="secondary" @click="exportData('json')">Экспорт JSON</button><button class="secondary" @click="exportData('csv')">Экспорт CSV</button></div></div><div class="viewer-grid"><div class="video-panel panel"><div class="video-frame"><video :src="trajectory.video.previewUrl" :controls="false" @timeupdate="(e)=>time=(e.target as HTMLVideoElement).currentTime"></video><div class="camera-dot" :style="{left:(25+(time/(video?.durationSec||1))*50)+'%',top:(58-Math.sin(time)*20)+'%'}"></div><span class="frame-label">{{time.toFixed(2)}} s</span></div><div class="transport"><button class="play" @click="toggle">{{playing?'Ⅱ':'▶'}}</button><input v-model.number="time" type="range" min="0" :max="video?.durationSec||1" step="0.01"><span class="num">{{time.toFixed(1)}} / {{video?.durationSec?.toFixed(1)}} s</span><select v-model.number="speed"><option :value="0.5">0.5×</option><option :value="1">1×</option><option :value="2">2×</option></select></div></div><div class="plot panel"><div class="plot-head"><div><span class="eyebrow">КАМЕРНЫЙ ПУТЬ</span><h3>{{view==='map'?'Проекция сверху':'Пространство'}}</h3></div><div class="segmented"><button :class="{active:view==='map'}" @click="view='map'">2D</button><button :class="{active:view==='space'}" @click="view='space'">3D</button></div></div><svg viewBox="0 0 560 300" role="img" aria-label="Проекция траектории"><path d="M 35 250 C 130 230 100 105 220 145 S 390 210 520 55" class="axis"/><path d="M 35 250 C 130 230 100 105 220 145 S 390 210 520 55" class="route" :stroke-dasharray="view==='space'?'6 8':'none'"/><circle cx="35" cy="250" r="5" class="start-dot"/><circle cx="520" cy="55" r="7" class="current-dot"/><text x="31" y="278">СТАРТ</text><text x="478" y="40">ТЕКУЩАЯ</text></svg><div class="plot-foot"><span><i class="legend estimated"></i>Оцененная поза</span><span><i class="legend gap"></i>Разрыв {{model?.quality.maxGapSec?.toFixed(1)||'—'}} с</span></div></div></div>
<div class="detail-grid"><section class="panel metrics"><div class="section-title"><h3>Качество результата</h3><span class="pill" :class="trajectory.warnings.length?'warn':''">{{trajectory.warnings.length?'Частичный':'Готово'}}</span></div><div class="metric-row"><div><span>Покрытие кадров</span><b>{{Math.round((model?.quality.coverage||0)*100)}}%</b></div><div><span>Зарегистрировано</span><b>{{model?.quality.registeredFrames}} / {{model?.quality.sampledFrames}}</b></div><div><span>Точки 3D</span><b>{{model?.quality.points3D?.toLocaleString('ru-RU')}}</b></div><div><span>Репроекция</span><b>{{model?.quality.meanReprojectionErrorPx?.toFixed(2)||'—'}} px</b></div></div><p class="note">Масштаб координат произвольный. Репроекционная ошибка описывает согласованность модели, а не точность пути в метрах.</p></section><section class="panel settings"><h3>Модель и параметры</h3><label>Компонент реконструкции<select v-model="modelId"><option v-for="m in trajectory.models" :key="m.id" :value="m.id">{{m.id}} · {{m.samples.filter(s=>s.status==='estimated').length}} поз</option></select></label><div class="setting-list"><span>Движок <b>{{trajectory.engine}}</b></span><span>Позы <b>{{trajectory.poseConvention}}</b></span><span>Частота <b>{{trajectory.settings.sampleHz}} Гц</b></span></div></section></div></section>
<section v-else class="empty-state panel"><span class="empty-mark">⌁</span><h2>Результат появится здесь</h2><p>После обработки путь, пропуски и качество будут синхронизированы с видео.</p></section><section class="saved"><div class="section-title"><div><p class="eyebrow">ИСТОРИЯ</p><h2>Сохранённые результаты</h2></div><button class="text-button" @click="loadSaved">Обновить</button></div><div v-if="saved.length" class="saved-list"><button v-for="item in saved" :key="item.runId" @click="load(item.runId)"><span><b>{{item.videoName}}</b><small>{{new Date(item.createdAt).toLocaleString('ru-RU')}} · {{item.state==='partial'?'частичный':'готово'}}</small></span><span class="num">{{item.registeredFrames}} / {{item.sampledFrames}} кадров →</span></button></div><p v-else class="muted">Сохранённых маршрутов пока нет.</p></section></main></div></template>
